// Case study pages (results/<slug>/index.html, generated by scripts/build-cases.mjs).
import { initSite, gsap, ScrollTrigger, reduceMotion, toast } from '../../ds/site.js';
import { CASES } from '../../content/cases.js';
import { $, $$, trackHeaderOffset, revealHeadings, scrollSpy, tocJump, magnetic, tilt } from '../results/shared.js';
import { mountGrowth3D } from '../results/growth3d.js';
import '../results/results.css';
import './case.css';

initSite();
trackHeaderOffset();
revealHeadings();

const slug = location.pathname.split('/').filter(Boolean).pop();
const data = CASES.find((c) => c.slug === slug);

// ---------------------------------------------------------------------------
// 3D hero: the case's own chart data as a growing 3D before/after bar chart (scroll-scrubbed)
// ---------------------------------------------------------------------------
const photo = $('.cs-hero__photo');
mountGrowth3D(photo, { series: data?.results.chart?.series.map((s) => s.values), scrub: true });
tilt(photo, 4);

// ---------------------------------------------------------------------------
// On this page: scroll-spy, stage mini-map, mobile dropdown
// ---------------------------------------------------------------------------
const toc = $('.cs-toc');
const toggle = $('.cs-toc__toggle');
const current = $('[data-toc-current]');
const setOpen = (open) => {
  toc.classList.toggle('is-open', open);
  toggle.setAttribute('aria-expanded', String(open));
};
toggle.addEventListener('click', () => setOpen(!toc.classList.contains('is-open')));
tocJump(toc, () => setOpen(false));
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && toc.classList.contains('is-open')) {
    setOpen(false);
    toggle.focus();
  }
});

scrollSpy($$('[data-spy]'), (id) => {
  const link = $(`[data-spy="${id}"]`);
  if (link) current.textContent = link.textContent.replace(/\s+/g, ' ').trim();
});
const stageLinks = $$('.is-used [data-spy-sub]');
scrollSpy(stageLinks, (id) => $$('.stage').forEach((s) => s.classList.toggle('is-current', s.id === id && !s.classList.contains('stage--off'))), { line: 0.5 });

// ---------------------------------------------------------------------------
// "How we measured": popover on desktop, bottom sheet on mobile
// ---------------------------------------------------------------------------
let openPop = null;
const closePop = (focusBtn) => {
  if (!openPop) return;
  const { btn, pop } = openPop;
  pop.hidden = true;
  btn.setAttribute('aria-expanded', 'false');
  if (focusBtn) btn.focus();
  openPop = null;
};
$$('.hwm-btn').forEach((btn) => {
  const pop = document.getElementById(btn.getAttribute('aria-controls'));
  btn.addEventListener('click', (e) => {
    e.stopPropagation();
    const wasOpen = openPop?.btn === btn;
    closePop();
    if (wasOpen) return;
    pop.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    openPop = { btn, pop };
    $('.hwm__close', pop).focus({ preventScroll: true });
    if (!reduceMotion) gsap.fromTo(pop, { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.35, ease: 'expo.out' });
  });
  $('.hwm__close', pop).addEventListener('click', () => closePop(true));
  pop.addEventListener('click', (e) => e.stopPropagation());
});
document.addEventListener('click', () => closePop());
document.addEventListener('keydown', (e) => e.key === 'Escape' && closePop(true));

// ---------------------------------------------------------------------------
// Share
// ---------------------------------------------------------------------------
const url = location.origin + location.pathname;
$$('[data-share]').forEach((a) => (a.href += encodeURIComponent(url)));
$('[data-copy-link]')?.addEventListener('click', async () => {
  try {
    await navigator.clipboard.writeText(url);
    toast({ title: 'Link copied', message: 'The case study link is on your clipboard.', type: 'success', duration: 3000 });
  } catch {
    toast({ title: 'Copy failed', message: url, type: 'error' });
  }
});

// ---------------------------------------------------------------------------
// Motion: scroll-scrubbed chart, stage choreography, magnetic CTAs
// ---------------------------------------------------------------------------
magnetic($$('.cs-cta .btn'));
const mm = gsap.matchMedia();
mm.add('(prefers-reduced-motion: no-preference)', () => {
  const chart = $('[data-chart]');
  if (chart) {
    const funnel = chart.classList.contains('chart--funnel');
    const tl = gsap.timeline({ scrollTrigger: { trigger: chart, start: 'top 85%', end: 'center 45%', scrub: 0.6 } });
    tl.from($$('.chart__bar', chart), {
      ...(funnel ? { scaleX: 0, transformOrigin: '0% 50%' } : { scaleY: 0, transformOrigin: '50% 100%' }),
      ease: 'power2.out',
      stagger: { each: 0.04, from: 'start' },
    });
    const values = $$('.chart__value', chart);
    if (values.length) tl.from(values, { opacity: 0, x: -6, stagger: 0.04 }, '<0.3');
  }
  // metrics: the "after" value slides in from the "before"
  $$('.metric').forEach((m) =>
    gsap.from($$('.metric__after, .metric__arrow', m), { x: -24, opacity: 0, duration: 0.9, ease: 'expo.out', stagger: 0.08, scrollTrigger: { trigger: m, start: 'top 85%' } }),
  );
  // unused stages fade to their dimmed state as the approach list passes
  if ($$('.stage--off').length) gsap.from('.stage--off', { opacity: 0, y: 16, duration: 0.6, stagger: 0.05, ease: 'power2.out', scrollTrigger: { trigger: '.stages', start: 'top 80%' } });
  gsap.from('.cs-nav__card', { y: 30, opacity: 0, duration: 0.8, stagger: 0.1, ease: 'expo.out', scrollTrigger: { trigger: '.cs-nav', start: 'top 90%' }, clearProps: 'transform,opacity' });
});

addEventListener('load', () => ScrollTrigger.refresh());
